import json

import numpy as np
from tle.core.rng import GameRng
from tle.engines.simulated import SimulatedEngine
from tle.mocks import bank_entry, evaluate_classifier, fit, load_reactions, write_bank
from tle.params import default_params
from tle.testing import catalogs


def _records(n_events=12, m=30, K=4, seed=0, beta=1.5):
    """Choices generated by the utility model itself with a known preference for the supportive option."""
    rng = np.random.default_rng(seed)
    recs = []
    for _ in range(n_events):
        stance = rng.choice([-1.0, -0.33, 0.33, 0.67], size=(K, 8))
        ctx = {
            "age_band": [2] * m,
            "social_class": rng.integers(0, 3, m).tolist(),
            "T": rng.integers(0, 7, (m, 4)).tolist(),
            "C": rng.integers(0, 7, (m, 3)).tolist(),
            "I": rng.integers(0, 7, (m, 3)).tolist(),
            "O": rng.integers(0, 7, (m, 6)).tolist(),
            "fear": [0] * m,
            "member": None,
        }
        u = beta * stance[:, 6][None, :] + rng.gumbel(size=(m, K))
        recs.append(
            {
                "kind": "reaction",
                "actor": {"kind": "mayor", "ideology": None},
                "event_type": "x",
                "ctx": ctx,
                "stance": stance.tolist(),
                "choice": u.argmax(axis=1).tolist(),
            }
        )
    return recs


def test_fit_recovers_a_preference_for_the_supportive_option():
    recs = _records()
    res = fit(recs)
    assert res["after"]["loglik"] > res["before"]["loglik"]
    assert (
        res["after"]["params"]["beta_support"] > 0.5
    )  # the generator prefers options that side with the actor
    assert res["after"]["loglik"] > res["uniform_loglik"]


def test_reactions_are_loaded_from_jsonl(tmp_path):
    f = tmp_path / "r.jsonl"
    f.write_text("\n".join(json.dumps(r) for r in _records(2)) + "\n" + json.dumps({"kind": "decree"}) + "\n")
    assert len(load_reactions([f])) == 2


def test_decree_bank_round_trip_and_neighbour_labels(tmp_path):
    cat = catalogs()
    eng = SimulatedEngine(cat, default_params(), perfect=True)
    out = eng.classify_text("Shut down critical newspapers")
    entry = bank_entry("Shut down critical newspapers", out)
    write_bank([entry], tmp_path / "bank.toml")
    import tomllib

    bank = tomllib.loads((tmp_path / "bank.toml").read_text())["decrees"]
    near = eng.classify_text("Shut down critical newspapers!", bank)  # a labelled decree is reproduced
    assert near.pillar == out.pillar == "press" and near.aggressiveness == out.aggressiveness
    assert evaluate_classifier(bank, leave_one_out=False)["pillar"] == 1.0


def test_narration_templates_give_readable_text_without_numbers():
    cat = catalogs()
    assert cat.narration["headline"]["demonstration"] and len(cat.narration["reactions"]) == 7
    from tle.contracts import models as m

    eng = SimulatedEngine(cat, default_params(), perfect=True)
    seed = m.EventSeed(
        event_id=1,
        day=3,
        parent=None,
        parent_context="",
        actor={"kind": "faction", "name": "The Greens"},
        event_type="demonstration",
        target={},
        intensity="high",
        involved_group="all adults",
        characters=[],
        can_found=False,
        n_options=10,
    )
    out = eng.call(
        "narrate_event",
        m.NarrateEventIn(seed=seed),
        GameRng(1),
    )
    assert "The Greens" in out.title and not any(ch.isdigit() for ch in out.text)
    assert len({o.text for o in out.options}) >= 4
